function countMailboxes(emails: string[]): number {
  const seen = new Set<string>();
  for (const e of emails) {
    let local = "";
    let i = 0;
    for (; e[i] !== "@" && e[i] !== "+"; i++) if (e[i] !== ".") local += e[i];
    seen.add(local + e.slice(e.indexOf("@")));
  }
  return seen.size;
}

